DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 136", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "f91630f4-3aab-523f-87f3-438f73c99dd8", "stem": "The vertical axis in the graph gives height in centimeters. Which option is closest to the height predicted by the line of best fit when the horizontal value is 2, expressed in meters?", "choices": [{"key": "A", "text": "0.30 m"}, {"key": "B", "text": "0.48 m"}, {"key": "C", "text": "0.55 m"}, {"key": "D", "text": "0.59 m"}], "type": "mcq", "correct": "B", "explanation": "At horizontal value 2, the fitted line is in the mid-to-upper 40s of centimeters (approximately 46–48 cm), or about 0.46–0.48 m. Among the choices, 0.48 m is closest.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 427", "note": "Complete original exam page 427 visually checked; answer independently solved and all choices checked. Original axis explicitly reads height (cm). Wording asks for the closest listed estimate, avoiding false exactness in a low-resolution fitted line.", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 143", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "334a53f0-1c9f-5230-8060-a4aeb202eab6", "stem": "A basketball player has probability 0.6 of making his first shot. If he misses the first shot, his probability of making the second is 0.3. What is the probability that he misses both shots?", "choices": [{"key": "A", "text": "0.18"}, {"key": "B", "text": "0.28"}, {"key": "C", "text": "0.30"}, {"key": "D", "text": "0.70"}], "type": "mcq", "correct": "B", "explanation": "P(first miss)=1−0.6=0.4. Conditional on that miss, P(second miss)=1−0.3=0.7. The multiplication rule gives 0.4·0.7=0.28.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 433", "note": "Complete original exam page 433 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:PAM 053", "old_status": "needs_source_reconstruction", "status": "defective_choices", "note": "Full original page 414 recovered. Simplification gives (x²−10x−26)/(10(x+3)), x≠4,−3. BOTH A and B are equivalent: A numerator x³−14x²+14x+104=(x−4)(x²−10x−26), and its denominator is 10(x−4)(x+3). Thus there are two correct original choices; kept excluded.", "verification_source": "New exams_251110_.pdf, physical page 414"}, {"id": "clean:PSD 091", "old_status": "needs_source_reconstruction", "status": "defective_choices", "note": "Full original page 105 recovered: German 25%, Swiss 45%, no dog 35%. Even assuming these are the only dog types, intersection is 5%, and P(Swiss|German)=5/25=0.2. I claims 11%, II claims 0.8, and III claims 0.05 as a conditional probability. None of the combinations is correct. Without the two-type assumption, the intersection is even less determined. Kept excluded.", "verification_source": "New exams_251110_.pdf, physical page 105"}, {"id": "clean:PAM 040", "old_status": "needs_source_reconstruction", "status": "defective_choices", "note": "Original page 106 restored. Graph is voltage in V against current in mA, with slope 16/40=0.4 V/mA (400 Ω in SI units). Its physical inverse is I_mA=2.5U or I_A=U/400. All choices are instead written as U in terms of I; no choice gives the inverse using the graphed units and variable roles. Kept excluded pending corrected inverse labels/units.", "verification_source": "New exams_251110_.pdf, physical page 106"}, {"id": "clean:MIX 025", "old_status": "worked_missing_choice", "status": "worked_missing_choice", "note": "Original page 433 confirms |3x−8|=−6 has no real solutions (D), but the numerator of choice C is also missing in this fuller original. A replacement distractor must not be invented.", "correct": "D", "verification_source": "New exams_251110_.pdf, physical page 433"}, {"id": "clean:MIX 026", "old_status": "defective_choices", "status": "needs_source_repair", "note": "Full original page 433 still says consecutive numbers without positivity. Products 12·13 and (−13)(−12) are both 156, giving sums 25 and −25. Only 25 is listed. The source does not determine a unique sum; kept excluded.", "verification_source": "New exams_251110_.pdf, physical page 433"}, {"id": "clean:PSD 170", "old_status": "worked_missing_choice", "status": "ready", "question_id": "333b9a74-a979-5118-b201-0a726fb0f1c6", "stem": "What is the equation of the line shown in the graph?", "choices": [{"key": "A", "text": "y=−2x+2"}, {"key": "B", "text": "y=0.5x+3"}, {"key": "C", "text": "y=2x+3"}, {"key": "D", "text": "y=−2x+3"}], "type": "mcq", "correct": "D", "explanation": "The intercepts are (0,3) and (1.5,0). The slope is (0−3)/(1.5−0)=−2, giving y=−2x+3.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 459", "note": "Complete original exam page 459 visually checked; answer independently solved and all choices checked. Recovered primary Q14. Adjacent Q15, |2x+1|>3, remains excluded because black blocks obscure its answer graphs; its solution is x<−2 or x>1.", "assets": {"unresolved_source_fragments": [{"original_question": "Q15", "reason": "Black blocks obscure graph choices; no verified letter", "worked_solution": "x<−2 or x>1", "release_hold": true}], "figure": "data:image/jpeg;base64,"}}, {"id": "clean:HOA 119", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "a1796f5b-aa1c-5189-8596-60d346bcb712", "stem": "If 4^(2−x)/2^x=1/8 and x=m/3 for real m, what is m?", "choices": [{"key": "A", "text": "7"}, {"key": "B", "text": "−3"}, {"key": "C", "text": "3"}, {"key": "D", "text": "1/3"}], "type": "mcq", "correct": "A", "explanation": "Write all powers with base 2: 4^(2−x)/2^x=2^(4−2x−x)=2^(4−3x). Since 1/8=2^(−3), 4−3x=−3, so x=7/3. Thus m=7.", "topic": "Algebra Foundations, Equations & Inequalities", "verification_source": "New exams_251110_.pdf, physical page 409", "note": "Complete original exam page 409 visually checked; answer independently solved and all choices checked. Full original page restores numerator exponent 2−x, denominator exponent x, and relation x=m/3.", "assets": {}}, {"id": "clean:HOA 123", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "99fe802c-3f1a-5c25-8366-4c73c748a4ee", "stem": "Find x if 27^(3x−1)=3^6.", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "1/3"}, {"key": "D", "text": "4"}], "type": "mcq", "correct": "A", "explanation": "Since 27=3³, the left side is 3^(9x−3). Equal powers of 3 give 9x−3=6, so x=1.", "topic": "Algebra Foundations, Equations & Inequalities", "verification_source": "New exams_251110_.pdf, physical page 411", "note": "Complete original exam page 411 visually checked; answer independently solved and all choices checked. Complete source restores exponent 3x−1 on 27, exponent 6 on 3, and all four choices.", "assets": {}}, {"id": "clean:PSD 130", "old_status": "needs_source_reconstruction", "status": "needs_source_repair", "note": "Full original page 412 restores Dalia’s initial score 70. A repeated observed 15% increase gives 70·1.15²=92.575≈93 (D), whereas treating 15% as a continuous rate gives 70e^0.3≈94.49, absent from the choices. The wording mixes these models. The adjacent email-graph question still asks an undefined “average rate of age” and offers fractions while requesting a whole number. Neither is released without correcting the wording.", "verification_source": "New exams_251110_.pdf, physical page 412"}, {"id": "clean:HOA 112", "old_status": "defective_choices", "status": "needs_source_repair", "note": "Full original page 408 confirms the ambiguous identity. Comparing coefficients gives a=8, c=4b, and b(1+c)=0. Both (b,c)=(0,0) and (−1/4,−1) satisfy it, giving a+8b+c=8 or 5. No b≠0 condition is stated. Kept excluded.", "verification_source": "New exams_251110_.pdf, physical page 408"}, {"id": "clean:HOA 137", "old_status": "needs_source_repair", "status": "needs_source_repair", "note": "Full original page 427 confirms the inconsistent polynomial identity. Leading, cubic, linear and constant coefficients force b²=4, z+f=9/2, a²=32/9 and zf=729/32. These force the quadratic coefficient to be 6305/72 instead of 5. No values satisfy the full identity; selecting b=2 from the leading term alone is invalid.", "verification_source": "New exams_251110_.pdf, physical page 427"}, {"id": "clean:HOA 144", "old_status": "defective_choices", "status": "defective_choices", "note": "Full original page 433 repeats (2i+3)(i+5)=7i+m. The left side equals 13+13i, so m=13+6i. None of the real choices 17,13,15,11 is correct. Kept excluded.", "verification_source": "New exams_251110_.pdf, physical page 433"}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
